<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForgePrintifyConnector\Preparation\{HeldPreparationReadModel,MutationIntent};
require_once __DIR__.'/../fixtures/printify-connector/stage34/companion-test-bootstrap.php';
final class PrintifyCompanionHeldPreparationTest extends TestCase {
 private function fixture():array{return (require __DIR__.'/../fixtures/printify-connector/sprint/held-source.php')();}
 public function testCoreSourceObservationNeverBecomesCanonicalApprovalOrPayloadEquivalence():void {
  self::assertTrue(class_exists(HeldPreparationReadModel::class),'Strict held-source consumer required.');[$s,$r]=$this->fixture();$o=HeldPreparationReadModel::observe($s,1,$r);self::assertIsArray($o);self::assertSame(6,$o['business_product_version_id']);self::assertNull($o['native_product_version']);self::assertFalse($o['mutation_authorized']);self::assertFalse($o['companion_payload_equivalence_verified']);self::assertFalse($o['trusted_receipt']);self::assertFalse($o['retry_permitted']);self::assertTrue($o['manual_review_required']);self::assertArrayNotHasKey('body',$o);
 }
 public static function invalid():array{return [['actor_id',2],['credential_reference',99],['provider_shop_id','99'],['authorization_revision',4],['version','2.0.0'],['schema','OTHER'],['native_product_version',0],['mutation_authorized',true],['independent_checkpoint_verified',true],['companion_payload_equivalence_verified',true],['external_execution_authorized',true],['release_hold',false],['product_version_id',0],['plan_policy_revision',0],['operation','PRODUCT_CREATE'],['operation','PRODUCT_UPDATE'],['operation','PRODUCT_DELETE'],['body',['private'=>'secret']]];}
 /** @dataProvider invalid */
 public function testForgedOrIncompatibleSourceIsRejectedEvenWhenRehashed(string $key,mixed $value):void {self::assertTrue(class_exists(HeldPreparationReadModel::class));[$s,$r]=$this->fixture();$r[$key]=$value;unset($r['evidence_hash']);$r['evidence_hash']=MutationIntent::hash($r);self::assertInstanceOf(WP_Error::class,HeldPreparationReadModel::observe($s,1,$r));}
 public function testHeldJournalIsObservedWithoutPromotingItsZeroPlaceholderToNativeVersion():void {
  self::assertTrue(method_exists(HeldPreparationReadModel::class,'fromRegistration'));[$s,$e]=$this->fixture();$b=['operation_id'=>str_repeat('d',64),'payload_fingerprint'=>$e['payload_fingerprint'],'intent_fingerprint'=>$e['evidence_hash'],'scope_fingerprint'=>$s->fingerprint(),'shop_id'=>2,'shop_key'=>$s->shopKey,'integration_id'=>7,'credential_reference'=>7,'provider_shop_id'=>'12','environment'=>'test','actor_id'=>1,'authorization_revision'=>3,'approval_reference'=>$e['plan_policy_hash'],'product_version'=>0,'expected_product_version'=>0];
  $record=['schema'=>'DF_NATIVE_HELD_JOURNAL_1','binding'=>$b,'candidate_key'=>str_repeat('f',64),'state'=>'HELD','revision'=>1,'fence_hash'=>null,'occurred_at'=>time(),'approval_verified'=>false,'dispatch_permitted'=>false,'independent_checkpoint_verified'=>false];
  $r=['schema'=>'DF_NATIVE_BUSINESS_MUTATION_REGISTRATION_1','version'=>'1.0.0','scope_fingerprint'=>$s->fingerprint(),'actor_id'=>1,'evidence'=>$e,'journal'=>['record'=>$record,'event_hash'=>str_repeat('e',64)],'approval_verified'=>false,'dispatch_permitted'=>false,'native_product_version'=>null,'native_version_counters_verified'=>false,'companion_payload_equivalence_verified'=>false,'native_contract_satisfied'=>false,'independent_checkpoint_verified'=>false,'external_execution_authorized'=>false,'release_hold'=>true];$r['evidence_hash']=MutationIntent::hash($r);
  $view=HeldPreparationReadModel::fromRegistration($s,1,$r);self::assertIsArray($view);self::assertSame('HELD_SOURCE_ONLY',$view['state']);self::assertNull($view['native_product_version']);self::assertFalse($view['mutation_authorized']);
  foreach(['UNKNOWN','FENCED','CANCELLED']as $state){$bad=$r;$bad['journal']['record']['state']=$state;unset($bad['evidence_hash']);$bad['evidence_hash']=MutationIntent::hash($bad);self::assertInstanceOf(WP_Error::class,HeldPreparationReadModel::fromRegistration($s,1,$bad));}
  $r['journal']['record']['binding']['credential_reference']=99;unset($r['evidence_hash']);$r['evidence_hash']=MutationIntent::hash($r);self::assertInstanceOf(WP_Error::class,HeldPreparationReadModel::fromRegistration($s,1,$r));
 }
 public function testDeferredShopThreeCannotSupplyHeldSourceEvenWithMatchingSelfHash():void {
  [$s,$r]=$this->fixture();$foreign=new DigiForge\Connector\Printify\ShopBinding(3,'standard_pod',7,'12','test',3,new DigiForge\Connector\Printify\CredentialReference(7),str_repeat('a',64),2000000000);$r['shop_key']='standard_pod';$r['scope_fingerprint']=$foreign->fingerprint();unset($r['evidence_hash']);$r['evidence_hash']=MutationIntent::hash($r);self::assertInstanceOf(WP_Error::class,HeldPreparationReadModel::observe($foreign,1,$r));
 }
 public function testNestedObjectsCannotExecuteWhileValidatingRegistrationHash():void {
  [$s,$e]=$this->fixture();$r=['schema'=>'DF_NATIVE_BUSINESS_MUTATION_REGISTRATION_1','version'=>'1.0.0','scope_fingerprint'=>$s->fingerprint(),'actor_id'=>1,'evidence'=>$e,'journal'=>[],'approval_verified'=>false,'dispatch_permitted'=>false,'native_product_version'=>null,'native_version_counters_verified'=>false,'companion_payload_equivalence_verified'=>false,'native_contract_satisfied'=>false,'independent_checkpoint_verified'=>false,'external_execution_authorized'=>false,'release_hold'=>true];$r['evidence_hash']=MutationIntent::hash($r);$calls=0;$hash=$e['package_hash'];$r['evidence']['package_hash']=new class($calls,$hash) implements JsonSerializable{public function __construct(private int &$calls,private string $hash){}public function jsonSerialize():mixed{++$this->calls;return $this->hash;}};
  self::assertInstanceOf(WP_Error::class,HeldPreparationReadModel::fromRegistration($s,1,$r));self::assertSame(0,$calls);
 }
 public function testTamperedHashAndMissingFieldsCannotBeNormalizedIntoReadiness():void {self::assertTrue(class_exists(HeldPreparationReadModel::class));[$s,$r]=$this->fixture();$r['evidence_hash']=str_repeat('0',64);self::assertInstanceOf(WP_Error::class,HeldPreparationReadModel::observe($s,1,$r));unset($r['plan_hash']);self::assertInstanceOf(WP_Error::class,HeldPreparationReadModel::observe($s,1,$r));}
}
